"""Round 27: the radio-link texts in every language of Órbita (orbita/static/i18n/<code>.json) and in idioma.js (en, pt)."""
import json, os, sys

K = ['Radioenlaces', 'Cadenas de microondas de torre en torre: donde no hay fibra entre pueblos, y las rutas rápidas de la bolsa.', 'Radioenlace de microondas',
     'Aquí internet viaja por el aire: de torre en torre, por microondas, siempre a la vista. Se usa donde tender fibra no compensa o no es posible, como el hielo, el desierto o el mar entre islas. La posición de cada torre no es pública: la línea une los pueblos que nombran las fuentes.',
     'radioenlaces de microondas, punteados, donde no hay fibra']
T = {
 'en': ['Radio links', 'Microwave chains from tower to tower, where no fibre runs between towns.', 'Microwave radio link', 'Here the internet travels through the air: from tower to tower, by microwave, always in line of sight. It is used where laying fibre does not pay or is not possible, such as ice, desert or the sea between islands. The position of each tower is not public: the line joins the towns the sources name.', 'microwave radio links, dotted, where there is no fibre'],
 'pt': ['Radioenlaces', 'Cadeias de micro-ondas de torre em torre, onde não há fibra entre as localidades.', 'Radioenlace de micro-ondas', 'Aqui a internet viaja pelo ar: de torre em torre, por micro-ondas, sempre em linha de vista. Usa-se onde instalar fibra não compensa ou não é possível, como no gelo, no deserto ou no mar entre ilhas. A posição de cada torre não é pública: a linha une as localidades que as fontes nomeiam.', 'radioenlaces de micro-ondas, pontilhados, onde não há fibra'],
 'pt-pt': ['Feixes hertzianos', 'Cadeias de micro-ondas de torre em torre, onde não há fibra entre as localidades.', 'Feixe hertziano de micro-ondas', 'Aqui a internet viaja pelo ar: de torre em torre, por micro-ondas, sempre em linha de vista. Usa-se onde instalar fibra não compensa ou não é possível, como no gelo, no deserto ou no mar entre ilhas. A posição de cada torre não é pública: a linha une as localidades que as fontes nomeiam.', 'feixes hertzianos de micro-ondas, pontilhados, onde não há fibra'],
 'fr': ['Faisceaux hertziens', 'Chaînes de micro-ondes de pylône en pylône, là où aucune fibre ne relie les localités.', 'Faisceau hertzien', 'Ici, internet passe par les airs : de pylône en pylône, par micro-ondes, toujours en visibilité directe. On l’utilise là où poser de la fibre n’est pas rentable ou pas possible, comme sur la glace, dans le désert ou en mer entre des îles. La position de chaque pylône n’est pas publique : la ligne relie les localités que citent les sources.', 'faisceaux hertziens, en pointillés, là où il n’y a pas de fibre'],
 'de': ['Richtfunk', 'Mikrowellenketten von Mast zu Mast, wo keine Glasfaser die Orte verbindet.', 'Richtfunkstrecke', 'Hier reist das Internet durch die Luft: von Mast zu Mast, per Mikrowelle, immer mit Sichtverbindung. Man nutzt es, wo sich Glasfaser nicht lohnt oder nicht möglich ist, etwa auf Eis, in der Wüste oder über dem Meer zwischen Inseln. Die Lage der einzelnen Masten ist nicht öffentlich: Die Linie verbindet die Orte, die die Quellen nennen.', 'Richtfunkstrecken, gepunktet, wo es keine Glasfaser gibt'],
 'it': ['Ponti radio', 'Catene di microonde da torre a torre, dove nessuna fibra collega i centri abitati.', 'Ponte radio a microonde', 'Qui internet viaggia nell’aria: da torre a torre, a microonde, sempre in linea di vista. Si usa dove posare la fibra non conviene o non è possibile, come sul ghiaccio, nel deserto o sul mare tra le isole. La posizione di ogni torre non è pubblica: la linea unisce i centri che citano le fonti.', 'ponti radio a microonde, punteggiati, dove non c’è fibra'],
 'nl': ['Straalverbindingen', 'Microgolfketens van mast naar mast, waar geen glasvezel tussen de plaatsen loopt.', 'Microgolfstraalverbinding', 'Hier reist het internet door de lucht: van mast naar mast, via microgolven, altijd in zichtlijn. Het wordt gebruikt waar glasvezel niet loont of niet kan, zoals op ijs, in de woestijn of over zee tussen eilanden. De ligging van elke mast is niet openbaar: de lijn verbindt de plaatsen die de bronnen noemen.', 'microgolfstraalverbindingen, gestippeld, waar geen glasvezel is'],
 'sv': ['Radiolänkar', 'Mikrovågskedjor från mast till mast, där ingen fiber går mellan orterna.', 'Mikrovågslänk', 'Här färdas internet genom luften: från mast till mast, med mikrovågor, alltid med fri sikt. Det används där fiber inte lönar sig eller inte går att dra, som på is, i öken eller över havet mellan öar. Varje masts läge är inte offentligt: linjen förbinder de orter som källorna nämner.', 'mikrovågslänkar, prickade, där det inte finns fiber'],
 'da': ['Radiokæder', 'Mikrobølgekæder fra mast til mast, hvor der ikke går fiber mellem byerne.', 'Mikrobølgeforbindelse', 'Her rejser internettet gennem luften: fra mast til mast, med mikrobølger, altid med frit udsyn. Det bruges, hvor fiber ikke kan betale sig eller ikke er muligt, som på is, i ørken eller over havet mellem øer. Den enkelte masts placering er ikke offentlig: linjen forbinder de byer, kilderne nævner.', 'mikrobølgeforbindelser, prikkede, hvor der ikke er fiber'],
 'nb': ['Radiolinjer', 'Mikrobølgekjeder fra mast til mast, der det ikke går fiber mellom stedene.', 'Mikrobølgelinje', 'Her reiser internett gjennom luften: fra mast til mast, med mikrobølger, alltid med fri sikt. Det brukes der fiber ikke lønner seg eller ikke er mulig, som på isen, i ørkenen eller over havet mellom øyer. Plasseringen av hver mast er ikke offentlig: linjen binder sammen stedene kildene nevner.', 'mikrobølgelinjer, prikkete, der det ikke finnes fiber'],
 'fi': ['Radiolinkit', 'Mikroaaltoketjuja mastosta mastoon siellä, missä paikkakuntien välillä ei ole kuitua.', 'Mikroaaltolinkki', 'Täällä internet kulkee ilmassa: mastosta mastoon mikroaalloilla, aina näköyhteydellä. Sitä käytetään siellä, missä kuidun vetäminen ei kannata tai ei ole mahdollista, kuten jäällä, aavikolla tai saarten välisellä merellä. Mastojen sijainnit eivät ole julkisia: viiva yhdistää lähteiden mainitsemat paikkakunnat.', 'mikroaaltolinkit, pisteviivalla, missä kuitua ei ole'],
 'is': ['Örbylgjusambönd', 'Örbylgjukeðjur frá mastri til masturs, þar sem enginn ljósleiðari liggur milli byggða.', 'Örbylgjusamband', 'Hér fer internetið um loftið: frá mastri til masturs, með örbylgjum, alltaf í sjónlínu. Það er notað þar sem ljósleiðari borgar sig ekki eða er ekki mögulegur, eins og á ís, í eyðimörk eða yfir haf milli eyja. Staðsetning hvers masturs er ekki opinber: línan tengir byggðirnar sem heimildirnar nefna.', 'örbylgjusambönd, punktalína, þar sem enginn ljósleiðari er'],
 'pl': ['Radiolinie', 'Łańcuchy mikrofalowe od masztu do masztu, tam gdzie między miejscowościami nie ma światłowodu.', 'Radiolinia mikrofalowa', 'Tu internet biegnie powietrzem: od masztu do masztu, mikrofalami, zawsze w linii wzroku. Stosuje się je tam, gdzie światłowód się nie opłaca lub jest niemożliwy, jak na lodzie, na pustyni czy nad morzem między wyspami. Położenie poszczególnych masztów nie jest publiczne: linia łączy miejscowości wymienione w źródłach.', 'radiolinie mikrofalowe, kropkowane, tam gdzie nie ma światłowodu'],
 'uk': ['Радіорелейні лінії', 'Мікрохвильові ланцюги від вежі до вежі там, де між населеними пунктами немає оптоволокна.', 'Мікрохвильова радіорелейна лінія', 'Тут інтернет передається повітрям: від вежі до вежі, мікрохвилями, завжди в прямій видимості. Його використовують там, де прокладати оптоволокно невигідно або неможливо: на кризі, у пустелі чи над морем між островами. Розташування кожної вежі не є публічним: лінія з’єднує населені пункти, названі в джерелах.', 'мікрохвильові радіорелейні лінії, пунктиром, де немає оптоволокна'],
 'ru': ['Радиорелейные линии', 'Микроволновые цепочки от вышки к вышке там, где между населёнными пунктами нет оптоволокна.', 'Микроволновая радиорелейная линия', 'Здесь интернет передаётся по воздуху: от вышки к вышке, микроволнами, всегда в прямой видимости. Его используют там, где прокладывать оптоволокно невыгодно или невозможно: на льду, в пустыне или над морем между островами. Расположение каждой вышки не публикуется: линия соединяет населённые пункты, названные в источниках.', 'микроволновые радиорелейные линии, пунктиром, где нет оптоволокна'],
 'tr': ['Radyolink hatları', 'Kasabalar arasında fiber olmayan yerlerde kuleden kuleye mikrodalga zincirleri.', 'Mikrodalga radyolink', 'Burada internet havadan gider: kuleden kuleye, mikrodalgayla, her zaman görüş hattında. Fiber döşemenin kârlı ya da mümkün olmadığı yerlerde kullanılır; buz, çöl ya da adalar arasındaki deniz gibi. Her kulenin konumu kamuya açık değildir: çizgi, kaynakların andığı yerleşimleri birleştirir.', 'mikrodalga radyolinkler, noktalı, fiber olmayan yerlerde'],
 'zh': ['微波中继', '在城镇之间没有光纤的地方，从一座铁塔到另一座铁塔的微波链路。', '微波中继链路', '在这里，互联网通过空中传输：从一座铁塔到另一座铁塔，借助微波，始终保持视距。它用于铺设光纤不划算或不可能的地方，例如冰原、沙漠或岛屿之间的海面。每座铁塔的位置并未公开：线条连接的是资料中提到的城镇。', '微波中继链路，以虚点表示，用于没有光纤的地方'],
 'zh-tw': ['微波中繼', '在城鎮之間沒有光纖的地方，從一座鐵塔到另一座鐵塔的微波鏈路。', '微波中繼鏈路', '在這裡，網際網路透過空中傳輸：從一座鐵塔到另一座鐵塔，藉由微波，始終保持視距。它用於鋪設光纖不划算或不可能的地方，例如冰原、沙漠或島嶼之間的海面。每座鐵塔的位置並未公開：線條連接的是資料中提到的城鎮。', '微波中繼鏈路，以虛點表示，用於沒有光纖的地方'],
 'ja': ['無線中継', '町と町の間に光ファイバーがない場所で、鉄塔から鉄塔へとつなぐマイクロ波の中継網。', 'マイクロ波無線中継', 'ここではインターネットが空中を伝わります。鉄塔から鉄塔へ、マイクロ波で、常に見通しのきく範囲で。氷原や砂漠、島と島の間の海など、光ファイバーを敷くのが割に合わない、または不可能な場所で使われます。各鉄塔の位置は公開されていません。線は資料に名前のある町を結んだものです。', 'マイクロ波無線中継（点線、光ファイバーのない場所）'],
 'ko': ['무선 중계', '마을 사이에 광섬유가 없는 곳에서 철탑에서 철탑으로 이어지는 마이크로파 중계망.', '마이크로파 무선 중계', '이곳에서는 인터넷이 공중으로 전달됩니다. 철탑에서 철탑으로, 마이크로파로, 항상 가시거리 안에서. 얼음 위나 사막, 섬 사이 바다처럼 광섬유를 까는 것이 수지가 맞지 않거나 불가능한 곳에서 쓰입니다. 각 철탑의 위치는 공개되지 않으며, 선은 자료에 나오는 마을을 이은 것입니다.', '마이크로파 무선 중계(점선, 광섬유가 없는 곳)'],
 'hi': ['रेडियो लिंक', 'जहाँ कस्बों के बीच फ़ाइबर नहीं है, वहाँ टावर से टावर तक माइक्रोवेव की कड़ियाँ।', 'माइक्रोवेव रेडियो लिंक', 'यहाँ इंटरनेट हवा से जाता है: टावर से टावर, माइक्रोवेव से, हमेशा सीधी दृष्टि में। इसका उपयोग वहाँ होता है जहाँ फ़ाइबर बिछाना फ़ायदेमंद या संभव नहीं, जैसे बर्फ़, रेगिस्तान या द्वीपों के बीच का समुद्र। हर टावर की स्थिति सार्वजनिक नहीं है: रेखा स्रोतों में बताए गए कस्बों को जोड़ती है।', 'माइक्रोवेव रेडियो लिंक, बिंदीदार, जहाँ फ़ाइबर नहीं है'],
 'bn': ['রেডিও লিংক', 'যেখানে শহরগুলোর মধ্যে ফাইবার নেই, সেখানে টাওয়ার থেকে টাওয়ারে মাইক্রোওয়েভের শৃঙ্খল।', 'মাইক্রোওয়েভ রেডিও লিংক', 'এখানে ইন্টারনেট বাতাসের মধ্য দিয়ে চলে: টাওয়ার থেকে টাওয়ারে, মাইক্রোওয়েভে, সবসময় সরাসরি দৃষ্টিসীমায়। যেখানে ফাইবার বসানো লাভজনক বা সম্ভব নয়, যেমন বরফ, মরুভূমি বা দ্বীপের মাঝের সমুদ্র, সেখানে এটি ব্যবহার হয়। প্রতিটি টাওয়ারের অবস্থান প্রকাশ্য নয়: রেখাটি সূত্রে উল্লেখিত শহরগুলোকে যুক্ত করে।', 'মাইক্রোওয়েভ রেডিও লিংক, বিন্দুযুক্ত, যেখানে ফাইবার নেই'],
 'id': ['Tautan radio', 'Rantai gelombang mikro dari menara ke menara, di tempat tanpa serat optik antarkota.', 'Tautan radio gelombang mikro', 'Di sini internet berjalan lewat udara: dari menara ke menara, dengan gelombang mikro, selalu dalam jarak pandang. Ini dipakai di tempat yang tidak menguntungkan atau tidak mungkin dipasangi serat optik, seperti es, gurun, atau laut di antara pulau. Posisi tiap menara tidak dipublikasikan: garisnya menghubungkan kota yang disebut sumber.', 'tautan radio gelombang mikro, bertitik, di tempat tanpa serat optik'],
 'ms': ['Pautan radio', 'Rantaian gelombang mikro dari menara ke menara, di tempat tiada gentian optik antara pekan.', 'Pautan radio gelombang mikro', 'Di sini internet bergerak melalui udara: dari menara ke menara, dengan gelombang mikro, sentiasa dalam garis penglihatan. Ia digunakan di tempat yang tidak berbaloi atau tidak mungkin dipasang gentian optik, seperti ais, gurun atau laut antara pulau. Kedudukan setiap menara tidak didedahkan: garisan menghubungkan pekan yang disebut sumber.', 'pautan radio gelombang mikro, bertitik, di tempat tiada gentian optik'],
 'vi': ['Vi ba chuyển tiếp', 'Chuỗi vi ba từ trạm này sang trạm khác, ở nơi không có cáp quang giữa các thị trấn.', 'Tuyến vi ba', 'Ở đây internet đi qua không khí: từ trạm này sang trạm khác, bằng vi ba, luôn trong tầm nhìn thẳng. Nó được dùng ở nơi kéo cáp quang không có lợi hoặc không thể, như trên băng, sa mạc hay biển giữa các đảo. Vị trí từng trạm không được công bố: đường kẻ nối các thị trấn mà nguồn nêu tên.', 'tuyến vi ba, nét chấm, ở nơi không có cáp quang'],
 'th': ['ลิงก์วิทยุ', 'สายโซ่ไมโครเวฟจากเสาสู่เสา ในที่ที่ไม่มีไฟเบอร์เชื่อมระหว่างเมือง', 'ลิงก์วิทยุไมโครเวฟ', 'ที่นี่อินเทอร์เน็ตเดินทางผ่านอากาศ จากเสาสู่เสาด้วยไมโครเวฟ และต้องมองเห็นกันเสมอ ใช้ในที่ที่วางไฟเบอร์ไม่คุ้มหรือทำไม่ได้ เช่น บนน้ำแข็ง ในทะเลทราย หรือบนทะเลระหว่างเกาะ ตำแหน่งของแต่ละเสาไม่ได้เปิดเผย เส้นนี้เชื่อมเมืองที่แหล่งข้อมูลระบุ', 'ลิงก์วิทยุไมโครเวฟ เส้นประจุด ในที่ที่ไม่มีไฟเบอร์'],
 'ar': ['الوصلات اللاسلكية', 'سلاسل موجات ميكروية من برج إلى برج، حيث لا توجد ألياف بين البلدات.', 'وصلة لاسلكية بالموجات الميكروية', 'هنا ينتقل الإنترنت عبر الهواء: من برج إلى برج، بالموجات الميكروية، دائمًا على خط البصر. يُستخدم حيث لا يجدي مدّ الألياف أو يتعذّر، كالجليد أو الصحراء أو البحر بين الجزر. موقع كل برج غير منشور: الخط يصل البلدات التي تذكرها المصادر.', 'وصلات لاسلكية بالموجات الميكروية، منقّطة، حيث لا توجد ألياف'],
 'fa': ['رادیولینک‌ها', 'زنجیره‌های مایکروویو از دکلی به دکل دیگر، جایی که میان شهرها فیبر نیست.', 'رادیولینک مایکروویو', 'اینجا اینترنت از راه هوا می‌رود: از دکلی به دکل دیگر، با مایکروویو، همیشه در خط دید. جایی به کار می‌رود که کشیدن فیبر به‌صرفه یا ممکن نیست، مثل یخ، بیابان یا دریای میان جزیره‌ها. جای هر دکل عمومی نیست: خط، شهرهایی را که منابع نام برده‌اند به هم وصل می‌کند.', 'رادیولینک‌های مایکروویو، نقطه‌چین، جایی که فیبر نیست'],
 'he': ['קישורי רדיו', 'שרשראות מיקרוגל מתורן לתורן, במקומות שאין בהם סיב בין היישובים.', 'קישור רדיו במיקרוגל', 'כאן האינטרנט עובר באוויר: מתורן לתורן, במיקרוגל, תמיד בקו ראייה. משתמשים בו היכן שהנחת סיב אינה משתלמת או אינה אפשרית, כמו על קרח, במדבר או בים שבין איים. מיקומו של כל תורן אינו פומבי: הקו מחבר את היישובים שהמקורות מזכירים.', 'קישורי רדיו במיקרוגל, מנוקדים, היכן שאין סיב'],
 'ur': ['ریڈیو لنکس', 'جہاں قصبوں کے درمیان فائبر نہیں، وہاں ٹاور سے ٹاور تک مائیکرو ویو کی کڑیاں۔', 'مائیکرو ویو ریڈیو لنک', 'یہاں انٹرنیٹ ہوا کے ذریعے جاتا ہے: ٹاور سے ٹاور، مائیکرو ویو سے، ہمیشہ سیدھی نظر میں۔ یہ وہاں استعمال ہوتا ہے جہاں فائبر بچھانا فائدہ مند یا ممکن نہیں، جیسے برف، صحرا یا جزیروں کے درمیان سمندر۔ ہر ٹاور کا مقام عوامی نہیں: لکیر ان قصبوں کو ملاتی ہے جن کا ذکر ذرائع میں ہے۔', 'مائیکرو ویو ریڈیو لنکس، نقطہ دار، جہاں فائبر نہیں'],
 'cs': ['Radioreléové spoje', 'Mikrovlnné řetězce od stožáru ke stožáru tam, kde mezi obcemi nevede optické vlákno.', 'Mikrovlnný radioreléový spoj', 'Tady internet putuje vzduchem: od stožáru ke stožáru, mikrovlnami, vždy na přímou viditelnost. Používá se tam, kde se optika nevyplatí nebo není možná, například na ledu, v poušti nebo nad mořem mezi ostrovy. Poloha jednotlivých stožárů není veřejná: čára spojuje obce, které uvádějí zdroje.', 'mikrovlnné radioreléové spoje, tečkovaně, kde není optika'],
 'sk': ['Rádioreléové spoje', 'Mikrovlnné reťazce od stožiara k stožiaru tam, kde medzi obcami nevedie optické vlákno.', 'Mikrovlnný rádioreléový spoj', 'Tu internet putuje vzduchom: od stožiara k stožiaru, mikrovlnami, vždy na priamu viditeľnosť. Používa sa tam, kde sa optika neoplatí alebo nie je možná, napríklad na ľade, v púšti alebo nad morom medzi ostrovmi. Poloha jednotlivých stožiarov nie je verejná: čiara spája obce, ktoré uvádzajú zdroje.', 'mikrovlnné rádioreléové spoje, bodkovane, kde nie je optika'],
 'ro': ['Radiolegături', 'Lanțuri de microunde din turn în turn, acolo unde nu există fibră între localități.', 'Radiolegătură prin microunde', 'Aici internetul călătorește prin aer: din turn în turn, prin microunde, mereu în linie de vedere. Se folosește acolo unde fibra nu merită sau nu e posibilă, cum ar fi pe gheață, în deșert sau pe mare între insule. Poziția fiecărui turn nu este publică: linia unește localitățile pe care le numesc sursele.', 'radiolegături prin microunde, punctate, acolo unde nu există fibră'],
 'hu': ['Mikrohullámú összeköttetések', 'Mikrohullámú láncok toronytól toronyig ott, ahol a települések között nincs optikai szál.', 'Mikrohullámú összeköttetés', 'Itt az internet a levegőben halad: toronytól toronyig, mikrohullámon, mindig rálátással. Ott használják, ahol az optika nem éri meg vagy nem lehetséges, például jégen, sivatagban vagy a szigetek közötti tengeren. Az egyes tornyok helye nem nyilvános: a vonal a forrásokban megnevezett településeket köti össze.', 'mikrohullámú összeköttetések, pontozva, ahol nincs optika'],
 'el': ['Μικροκυματικές ζεύξεις', 'Αλυσίδες μικροκυμάτων από πύργο σε πύργο, όπου δεν υπάρχει οπτική ίνα ανάμεσα στους οικισμούς.', 'Μικροκυματική ζεύξη', 'Εδώ το διαδίκτυο ταξιδεύει από τον αέρα: από πύργο σε πύργο, με μικροκύματα, πάντα σε οπτική επαφή. Χρησιμοποιείται όπου η οπτική ίνα δεν συμφέρει ή δεν γίνεται, όπως στον πάγο, στην έρημο ή στη θάλασσα ανάμεσα σε νησιά. Η θέση κάθε πύργου δεν είναι δημόσια: η γραμμή ενώνει τους οικισμούς που αναφέρουν οι πηγές.', 'μικροκυματικές ζεύξεις, με τελείες, όπου δεν υπάρχει οπτική ίνα'],
 'bg': ['Радиорелейни връзки', 'Микровълнови вериги от кула до кула, където между селищата няма оптично влакно.', 'Микровълнова радиорелейна връзка', 'Тук интернетът минава по въздуха: от кула до кула, с микровълни, винаги в пряка видимост. Използва се там, където полагането на оптика не си струва или е невъзможно, като на лед, в пустиня или над морето между острови. Местоположението на всяка кула не е публично: линията свързва селищата, които назовават източниците.', 'микровълнови радиорелейни връзки, пунктирани, където няма оптика'],
 'hr': ['Radiorelejne veze', 'Mikrovalni lanci od tornja do tornja, gdje između naselja nema optike.', 'Mikrovalna radiorelejna veza', 'Ovdje internet putuje zrakom: od tornja do tornja, mikrovalovima, uvijek u liniji vidljivosti. Koristi se gdje se optika ne isplati ili nije moguća, kao na ledu, u pustinji ili na moru između otoka. Položaj svakog tornja nije javan: crta spaja naselja koja navode izvori.', 'mikrovalne radiorelejne veze, točkasto, gdje nema optike'],
 'fil': ['Mga radio link', 'Mga kadena ng microwave mula tore hanggang tore, kung saan walang fiber sa pagitan ng mga bayan.', 'Microwave radio link', 'Dito, dumaraan sa hangin ang internet: mula tore hanggang tore, sa microwave, laging magkatanaw. Ginagamit ito kung saan hindi sulit o hindi posible ang fiber, gaya ng yelo, disyerto o dagat sa pagitan ng mga isla. Hindi pampubliko ang lokasyon ng bawat tore: pinagdudugtong ng linya ang mga bayang binabanggit ng mga pinagmulan.', 'mga microwave radio link, may tuldok, kung saan walang fiber'],
 'sw': ['Viungo vya redio', 'Minyororo ya mawimbi madogo kutoka mnara hadi mnara, mahali pasipo na fiber kati ya miji.', 'Kiungo cha redio cha mawimbi madogo', 'Hapa intaneti husafiri hewani: kutoka mnara hadi mnara, kwa mawimbi madogo, kila mara kwa kuonana moja kwa moja. Hutumika pale ambapo kuweka fiber hakulipi au hakuwezekani, kama kwenye barafu, jangwani au baharini kati ya visiwa. Mahali pa kila mnara si pa umma: mstari unaunganisha miji inayotajwa na vyanzo.', 'viungo vya redio vya mawimbi madogo, vya nukta, mahali pasipo na fiber'],
 'ta': ['வானொலி இணைப்புகள்', 'ஊர்களுக்கு இடையே ஃபைபர் இல்லாத இடங்களில் கோபுரத்திலிருந்து கோபுரத்திற்கு நுண்ணலைச் சங்கிலிகள்.', 'நுண்ணலை வானொலி இணைப்பு', 'இங்கே இணையம் காற்றின் வழியே செல்கிறது: கோபுரத்திலிருந்து கோபுரத்திற்கு, நுண்ணலையால், எப்போதும் நேர்ப்பார்வையில். ஃபைபர் போடுவது லாபமில்லாத அல்லது இயலாத இடங்களில், பனி, பாலைவனம், தீவுகளுக்கு இடையிலான கடல் போன்றவற்றில் இது பயன்படுகிறது. ஒவ்வொரு கோபுரத்தின் இடமும் பொதுவில் இல்லை: கோடு, ஆதாரங்கள் குறிப்பிடும் ஊர்களை இணைக்கிறது.', 'நுண்ணலை வானொலி இணைப்புகள், புள்ளிக்கோடாக, ஃபைபர் இல்லாத இடங்களில்'],
 'te': ['రేడియో లింకులు', 'పట్టణాల మధ్య ఫైబర్ లేని చోట టవర్ నుంచి టవర్‌కు మైక్రోవేవ్ గొలుసులు.', 'మైక్రోవేవ్ రేడియో లింక్', 'ఇక్కడ ఇంటర్నెట్ గాలి ద్వారా వెళ్తుంది: టవర్ నుంచి టవర్‌కు, మైక్రోవేవ్‌తో, ఎప్పుడూ నేరుగా కనిపించే దూరంలో. ఫైబర్ వేయడం లాభం లేని లేదా సాధ్యం కాని చోట, మంచు, ఎడారి లేదా దీవుల మధ్య సముద్రం వంటి చోట దీన్ని వాడతారు. ప్రతి టవర్ స్థానం బహిరంగం కాదు: గీత ఆధారాలు పేర్కొన్న పట్టణాలను కలుపుతుంది.', 'మైక్రోవేవ్ రేడియో లింకులు, చుక్కల గీతతో, ఫైబర్ లేని చోట'],
}

def main(raiz):
    d = os.path.join(raiz, 'orbita', 'static', 'i18n')
    for f in sorted(os.listdir(d)):
        if not f.endswith('.json'): continue
        c = f[:-5]
        if c not in T: sys.exit('falta ' + c)
        p = os.path.join(d, f); raw = open(p, encoding='utf-8').read(); j = json.loads(raw)
        for k, v in zip(K, T[c]): j['t'][k] = v
        open(p, 'w', encoding='utf-8').write(json.dumps(j, ensure_ascii=False, indent=1) + ('\n' if raw.endswith('\n') else ''))
    p = os.path.join(raiz, 'orbita', 'static', 'idioma.js'); s = open(p, encoding='utf-8').read()
    ancla = "    'De compañías con 1 a 4 centros de datos en el mapa, o sin operador conocido.':"
    i = s.index(ancla); i = s.index('\n', i) + 1
    nuevas = ''.join('    %s: [%s, %s],\n' % (json.dumps(k, ensure_ascii=False), json.dumps(e, ensure_ascii=False), json.dumps(pt, ensure_ascii=False)) for k, e, pt in zip(K, T['en'], T['pt']) if json.dumps(k, ensure_ascii=False) + ':' not in s)
    open(p, 'w', encoding='utf-8').write(s[:i] + nuevas + s[i:])
    print('ok', len(T))

if __name__ == '__main__':
    main(sys.argv[1])
